         // Original Doppler temperature shift.\n          temperature /= max(0.001, ray_doppler_factor * doppler_factor);\n\n          color += texture2D(accretion_disk_texture, tex_coord) *\n            accretion_intensity *\n            BLACK_BODY_COLOR(temperature);\n        }\n      }\n    }\n\n    // A little gravitational time evolution is retained through t.\n    t -= dt;\n\n    // Event horizon is u = 1 in the normalized units used by the original.\n    if (u > 1.0) break;\n  }\n\n  // ------------------------------------------------------------\n  // BACKGROUND STARS\n  // ------------------------------------------------------------\n  if (u < 1.0) {\n    ray = normalize(pos - old_pos);\n    vec2 tex_coord = sphere_map(ray * BG_COORDS);\n\n    vec4 star_color = texture2D(star_texture, tex_coord);\n\n    if (star_color.r > 0.0) {\n      float t_coord = (\n        STAR_MIN_TEMPERATURE +\n        (STAR_MAX_TEMPERATURE - STAR_MIN_TEMPERATURE) * star_color.g\n      ) / max(0.001, ray_doppler_factor);\n\n      color += BLACK_BODY_COLOR(t_coord) * star_color.r * STAR_BRIGHTNESS;\n    }\n  }\n\n  gl_FragColor = color * ray_intensity;\n}\n\n"},8671:(n,e,t)=>{"use strict";t.d(e,{LoadingProvider:()=>l,M:()=>c});var o=t(5155),r=t(2115),a=t(5695),s=t(6766);let i=(0,r.createContext)(null);function c(){let n=(0,r.useContext)(i);if(!n)throw Error("useLoading must be used within <LoadingProvider />");return n}function l(n){let{children:e}=n,t=(0,a.usePathname)(),[s,c]=(0,r.useState)(!0),[l,p]=(0,r.useState)(!1),u=(0,r.useRef)(null),m=(0,r.useRef)(null),h=(0,r.useRef)(Date.now()),x=()=>{u.current&&window.clearTimeout(u.current),m.current&&window.clearTimeout(m.current),u.current=null,m.current=null},g=()=>{x(),h.current=Date.now(),c(!0),p(!1)},f=()=>{x();let n=Math.max(0,1500-(Date.now()-h.current));m.current=window.setTimeout(()=>{p(!0),u.current=window.setTimeout(()=>{c(!1),p(!1),u.current=null},520)},n)};(0,r.useEffect)(()=>{h.current=Date.now(),f()},[]),(0,r.useEffect)(